/// Covariance prepared at the solution (root.assemble_covariance);
/// queries answer per-entity marginal blocks. Valid until the model
/// is dropped or reassembled.
class Covariance {
public:
    Covariance() : h_(nullptr) {}
    explicit Covariance(ffi::Fit* h) : h_(h) {}
    /// Per-parameter standard deviations into out; returns the count
    /// or a negative code. Works on every CovMode incl. TriDiagonal.
    int32_t std_dev(const N& e, double* out, uint32_t cap) {
        return ffi::fit_n_std_dev(h_, e.raw(), out, cap);
    }
    /// Row-major dim x dim conditional covariance (all other
    /// parameters held fixed) into out; returns dim or a negative code.
    int32_t conditional(const N& e, double* out, uint32_t cap) {
        return ffi::fit_n_conditional_cov(h_, e.raw(), out, cap);
    }
    result<double, CovError> marginal(const N& e) {
        double b[1];
        if (ffi::fit_n_marginal_cov(h_, e.raw(), b, 1) < 0) return fail<double>();
        return result<double, CovError>::ok(b[0]);
    }
    /// Per-parameter standard deviations into out; returns the count
    /// or a negative code. Works on every CovMode incl. TriDiagonal.
    int32_t std_dev(const Pose& e, double* out, uint32_t cap) {
        return ffi::fit_pose_std_dev(h_, e.raw(), out, cap);
    }
    /// Row-major dim x dim conditional covariance (all other
    /// parameters held fixed) into out; returns dim or a negative code.
    int32_t conditional(const Pose& e, double* out, uint32_t cap) {
        return ffi::fit_pose_conditional_cov(h_, e.raw(), out, cap);
    }
    /// Row-major dim x dim into out; returns dim or a negative code.
    int32_t marginal(const Pose& e, double* out, uint32_t cap) {
        return ffi::fit_pose_marginal_cov(h_, e.raw(), out, cap);
    }
    /// Row-major N::param_count x N::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const N& a, const N& b, double* out, uint32_t cap) {
        return ffi::fit_n_n_cross_cov(h_, a.raw(), b.raw(), out, cap);
    }
    /// Row-major N::param_count x Pose::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const N& a, const Pose& b, double* out, uint32_t cap) {
        return ffi::fit_n_pose_cross_cov(h_, a.raw(), b.raw(), out, cap);
    }
    /// Row-major Pose::param_count x N::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const Pose& a, const N& b, double* out, uint32_t cap) {
        return ffi::fit_pose_n_cross_cov(h_, a.raw(), b.raw(), out, cap);
    }
    /// Row-major Pose::param_count x Pose::param_count cross-covariance
    /// into out; returns the row count or a negative code.
    int32_t cross(const Pose& a, const Pose& b, double* out, uint32_t cap) {
        return ffi::fit_pose_pose_cross_cov(h_, a.raw(), b.raw(), out, cap);
    }
private:
    template<class T> result<T, CovError> fail() {
        return result<T, CovError>::err({ffi::fit_last_error(h_)});
    }
    ffi::Fit* h_;
};

/// `Fit.obs`. std::vec::Vec storage: pushes may MOVE elements -- re-fetch element refs after a push.
class FitObsVec {
public:
    explicit FitObsVec(ffi::Fit* h) : h_(h) {}
    uint32_t size() const { return ffi::fit_obs_len(h_); }
    bool empty() const { return size() == 0; }
    void reserve(uint32_t additional) { ffi::fit_obs_reserve(h_, additional); }
    Obs push() { return Obs(ffi::fit_obs_push(h_)); }
    Obs operator[](uint32_t i) { return Obs(ffi::fit_obs_at(h_, i)); }
    /// Front/back of a non-empty vec (empty = UB, like STL).
    Obs front() { return (*this)[0]; }
    Obs back() { return (*this)[size() - 1]; }
    /// Drops the last element; false when already empty.
    bool pop() { return ffi::fit_obs_pop(h_); }
    void clear() { ffi::fit_obs_clear(h_); }
    void truncate(uint32_t n) { ffi::fit_obs_truncate(h_, n); }
    /// Bidirectional iterator. Standard C++ contract: modifying the
    /// container while iterating is undefined behavior. Dereference
    /// yields a value wrapper (Obs), like vector<bool> --
    /// reference is a value type.
    class iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = Obs;
        using difference_type = std::ptrdiff_t;
        using reference = Obs;
        struct arrow { Obs v; Obs* operator->() { return &v; } };
        using pointer = arrow;

        iterator() : h_(nullptr), i_(0) {}
        iterator(ffi::Fit* h, uint32_t i) : h_(h), i_(i) {}
        Obs operator*() const { return Obs(ffi::fit_obs_at(h_, i_)); }
        arrow operator->() const { return arrow{**this}; }
        iterator& operator++() { ++i_; return *this; }
        iterator& operator--() { --i_; return *this; }
        iterator operator++(int) { iterator t = *this; ++*this; return t; }
        iterator operator--(int) { iterator t = *this; --*this; return t; }
        bool operator==(const iterator& o) const { return i_ == o.i_; }
        bool operator!=(const iterator& o) const { return i_ != o.i_; }
    private:
        ffi::Fit* h_;
        uint32_t i_;
    };
    iterator begin() { return iterator(h_, 0); }
    iterator end() { return iterator(h_, size()); }
    class reverse_iterator {
    public:
        using iterator_category = std::bidirectional_iterator_tag;
        using value_type = Obs;
        using difference_type = std::ptrdiff_t;
        using reference = Obs;
        using pointer = iterator::arrow;

        reverse_iterator() {}
        explicit reverse_iterator(iterator base) : base_(base) {}
        iterator base() const { return base_; }
        Obs operator*() const { iterator t = base_; --t; return *t; }
        pointer operator->() const { return pointer{**this}; }
        reverse_iterator& operator++() { --base_; return *this; }
        reverse_iterator& operator--() { ++base_; return *this; }
        reverse_iterator operator++(int) { reverse_iterator t = *this; ++*this; return t; }
        reverse_iterator operator--(int) { reverse_iterator t = *this; --*this; return t; }
        bool operator==(const reverse_iterator& o) const { return base_ == o.base_; }
        bool operator!=(const reverse_iterator& o) const { return base_ != o.base_; }
    private:
        iterator base_;
    };
    reverse_iterator rbegin() { return reverse_iterator(end()); }
    reverse_iterator rend() { return reverse_iterator(begin()); }
private:
    ffi::Fit* h_;
};

